const  caculateAvgRating = reviews =>{
    const totalRating = reviews?.reduce((acc, item) => acc + item.rating, 0)
    const avgRating =
        totalRating === 0
            ? ""
            : totalRating === 1
                ? totalRating
                : (totalRating / reviews?.length).to;
return {
    totalRating,
    avgRating
}
}
export default caculateAvgRating
